    """Restore the color-2 occlusion using the square's dihedral symmetries."""
    n = len(grid)
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 2:
                continue
            # The source pattern is invariant under the square's rotations/reflections.
            orbit = {(r, c), (c, r), (n - 1 - r, c), (r, n - 1 - c),
